#import <Foundation/Foundation.h>
#import "../ShareExtension/TFShareLauncher.h"
static int checks=0;static void Check(BOOL v,NSString *s){checks++;if(!v){NSLog(@"FAIL %@",s);exit(1);}}
static void Pump(double seconds){NSDate *end=[NSDate dateWithTimeIntervalSinceNow:seconds];while(end.timeIntervalSinceNow>0)[NSRunLoop.currentRunLoop runMode:NSDefaultRunLoopMode beforeDate:end];}
static TFShareLauncher *New(void){TFShareLauncher *v=[TFShareLauncher new];v.timeout=.04;return v;}
int main(){@autoreleasepool{
 NSString *job=NSUUID.UUID.UUIDString;
 TFShareLauncher *success=New();__block int primary=0,fallback=0,opened=0;
 success.primary=^(NSURL *url,void(^done)(BOOL)){primary++;Check([url.scheme isEqual:@"tweakforge"]&&[url.host isEqual:@"incoming"],@"own app fixed URL");Check([url.query containsString:job],@"opaque job only");done(YES);};success.fallback=^(NSURL *url,void(^done)(BOOL)){fallback++;done(NO);};success.updated=^(NSDictionary *s){if([s[@"state"] isEqual:@"opened"])opened++;};
 Check([success openIncomingJob:job],@"first launch accepted");Check(primary==1&&fallback==0&&opened==1,@"primary success no duplicate fallback");Check(![success openIncomingJob:job],@"opened job not relaunched");Pump(.05);Check([success.snapshot[@"state"] isEqual:@"opened"],@"timeout cannot overwrite success");
 TFShareLauncher *second=New();__block int secondCount=0;second.primary=^(NSURL *u,void(^done)(BOOL)){done(NO);done(NO);};second.fallback=^(NSURL *u,void(^done)(BOOL)){secondCount++;done(YES);};[second openIncomingJob:job];Check([second.snapshot[@"state"] isEqual:@"opened"]&&secondCount==1,@"one fallback on primary rejection");
 TFShareLauncher *denied=New();denied.primary=^(NSURL *u,void(^done)(BOOL)){done(NO);};denied.fallback=^(NSURL *u,void(^done)(BOOL)){done(NO);};[denied openIncomingJob:job];Check([denied.snapshot[@"state"] isEqual:@"failed"],@"both declined visible failure");Check([denied.snapshot[@"attempts"] count]==2,@"methods recorded");denied.primary=^(NSURL *u,void(^done)(BOOL)){done(YES);};Check([denied openIncomingJob:job],@"explicit retry allowed");Check([denied.snapshot[@"state"] isEqual:@"opened"],@"retry succeeds");
 TFShareLauncher *delayed=New();delayed.primary=^(NSURL *u,void(^done)(BOOL)){};delayed.fallback=^(NSURL *u,void(^done)(BOOL)){done(YES);};[delayed openIncomingJob:job];Check(![delayed openIncomingJob:job],@"pending attempt not duplicated");Pump(.03);Check([delayed.snapshot[@"state"] isEqual:@"opened"],@"fallback if primary callback missing");
 TFShareLauncher *timeout=New();__block void(^oldPrimary)(BOOL);timeout.primary=^(NSURL *u,void(^done)(BOOL)){oldPrimary=[done copy];};timeout.fallback=^(NSURL *u,void(^done)(BOOL)){};[timeout openIncomingJob:job];Pump(.05);Check([timeout.snapshot[@"state"] isEqual:@"failed"],@"bounded timeout");Check([timeout.snapshot[@"reason"] isEqual:@"openCallbackTimeout"],@"timeout reason recorded");void(^stale)(BOOL)=[oldPrimary copy];Check([timeout openIncomingJob:job],@"retry after timeout");stale(YES);Check([timeout.snapshot[@"state"] isEqual:@"opening"],@"old callback ignored during retry");oldPrimary(YES);Check([timeout.snapshot[@"state"] isEqual:@"opened"],@"current callback accepted");
 TFShareLauncher *invalid=New();__block int invalidCalls=0;invalid.primary=^(NSURL *u,void(^done)(BOOL)){invalidCalls++;};Check(![invalid openIncomingJob:@"file:///bad"],@"invalid job rejected");Check(invalidCalls==0&&[invalid.snapshot[@"state"] isEqual:@"idle"],@"invalid input has no launch side effects");
 TFShareLauncher *background=New();background.primary=^(NSURL *u,void(^done)(BOOL)){dispatch_async(dispatch_get_global_queue(QOS_CLASS_DEFAULT,0),^{done(YES);});};[background openIncomingJob:job];Pump(.02);Check([background.snapshot[@"state"] isEqual:@"opened"],@"background callback marshaled to main");
 NSLog(@"PASS %d share launch checks",checks);
}}
